#include "r3_local_rank_common.hpp"
struct Matching3{array<uint16_t,3> p; uint16_t u;};
Multiset canon3(const Multiset&x){int deg[7]={};for(int i=0;i<x.n;i++)for(int v:SUP[x.a[i]])deg[v]++;vector<int>vals(deg,deg+7);sort(vals.begin(),vals.end(),greater<int>());vals.erase(unique(vals.begin(),vals.end()),vals.end());vector<vector<int>>gs;for(int d:vals){vector<int>g;for(int v=0;v<7;v++)if(deg[v]==d)g.push_back(v);gs.push_back(g);}Multiset best;best.n=x.n;bool initv=false;int rel[7];function<void(int,int)>rec=[&](int gi,int off){if(gi==(int)gs.size()){Multiset im;im.n=x.n;for(int i=0;i<x.n;i++){int bits=0;for(int v:SUP[x.a[i]])bits|=1<<rel[v];im.a[i]=SI[bits];}sort(im.a.begin(),im.a.begin()+im.n);if(!initv||lexicographical_compare(im.a.begin(),im.a.begin()+im.n,best.a.begin(),best.a.begin()+best.n)){best=im;initv=true;}return;}auto g=gs[gi];sort(g.begin(),g.end());do{for(int j=0;j<(int)g.size();j++)rel[g[j]]=off+j;rec(gi+1,off+g.size());}while(next_permutation(g.begin(),g.end()));};rec(0,0);return best;}
array<BD,35>bdata3(const Multiset&ms,uint64_t&t){int mult[35]={};for(int i=0;i<ms.n;i++)mult[ms.a[i]]++;array<BD,35>o{};t=0;for(int b=0;b<35;b++){int tb=0;for(int v:TRI[b])tb|=1<<v;uint16_t m=0;bool rep=false;for(int i=0;i<ms.n;i++){int sb=0;for(int v:SUP[ms.a[i]])sb|=1<<v;if((sb&tb)!=tb)continue;m|=uint16_t(1u<<i);if(mult[ms.a[i]]>=2)rep=true;}int inc=popcount((unsigned)m);if(!inc)continue;t|=1ULL<<b;o[b]={m,rep,inc};}return o;}
inline bool sharp3(const BD&x,const array<uint16_t,3>&pm){for(auto m:pm) if(popcount((unsigned)(x.mask&~m))<2) return false; return true;}
inline bool empty3(const BD&x,const array<uint16_t,3>&pm){if(x.repeated)return x.inc>=4;if(x.inc>=3)return true;if(x.inc!=2)return false;for(auto m:pm)if(x.mask==m)return true;return false;}
inline bool single3(const BD&x,const array<uint16_t,3>&pm){if(!sharp3(x,pm))return false;return x.repeated?x.inc>=4:x.inc>=2;}
void init3(){fill(begin(SI),end(SI),-1);fill(begin(TI),end(TI),-1);fill(begin(EI),end(EI),-1);for(int a=0;a<7;a++)for(int b=a+1;b<7;b++)for(int c=b+1;c<7;c++)for(int d=c+1;d<7;d++){int bits=(1<<a)|(1<<b)|(1<<c)|(1<<d);SI[bits]=SUP.size();SUP.push_back({a,b,c,d});}for(int a=0;a<7;a++)for(int b=a+1;b<7;b++)for(int c=b+1;c<7;c++){int bits=(1<<a)|(1<<b)|(1<<c);TI[bits]=TRI.size();TRI.push_back({a,b,c});}for(int a=0;a<7;a++)for(int b=a+1;b<7;b++){EI[(1<<a)|(1<<b)]=ED.size();ED.push_back({a,b});}for(int b=0;b<35;b++){TROW[b].fill(0);int a=TRI[b][0],c=TRI[b][1],d=TRI[b][2];TROW[b][EI[(1<<c)|(1<<d)]]=1;TROW[b][EI[(1<<a)|(1<<d)]]=-1;TROW[b][EI[(1<<a)|(1<<c)]]=1;}}
bool ll3(){long long s=4;for(int i=0;i<29;i++)s=(s*s-2)%MOD;return s==0;}
unordered_set<Multiset,MH> build_reps3(){vector<long long>exp={1,1,4,14,61,268,1283,6032,27763};unordered_set<Multiset,MH>reps;Multiset e;reps.insert(e);for(int sz=1;sz<=8;sz++){unordered_set<Multiset,MH>n;n.reserve(reps.size()*8);for(auto&ms:reps){int mult[35]={};for(int i=0;i<ms.n;i++)mult[ms.a[i]]++;for(int s=0;s<35;s++)if(mult[s]<3){Multiset x=ms;x.a[x.n++]=s;sort(x.a.begin(),x.a.begin()+x.n);n.insert(canon3(x));}}reps.swap(n);if((long long)reps.size()!=exp[sz])throw 12;}return reps;}
vector<Matching3> build_matchings3(){vector<Matching3> out;for(int u0=0;u0<8;u0++)for(int u1=u0+1;u1<8;u1++){vector<int> r;for(int i=0;i<8;i++)if(i!=u0&&i!=u1)r.push_back(i);int a=r[0];for(int ib=1;ib<6;ib++){int b=r[ib];vector<int> rest;for(int x:r)if(x!=a&&x!=b)rest.push_back(x);int c=rest[0];for(int id=1;id<4;id++){int d=rest[id];vector<int> last;for(int x:rest)if(x!=c&&x!=d)last.push_back(x);array<uint16_t,3> p={uint16_t((1u<<a)|(1u<<b)),uint16_t((1u<<c)|(1u<<d)),uint16_t((1u<<last[0])|(1u<<last[1]))};sort(p.begin(),p.end());out.push_back({p,uint16_t((1u<<u0)|(1u<<u1))});}}}sort(out.begin(),out.end(),[](auto&A,auto&B){if(A.u!=B.u)return A.u<B.u;return A.p<B.p;});out.erase(unique(out.begin(),out.end(),[](auto&A,auto&B){return A.u==B.u&&A.p==B.p;}),out.end());if(out.size()!=420)throw 13;return out;}
bool survivor3(const array<BD,35>&d,uint64_t T,const Matching3&m,long long&placements,long long&passes){int rt=trank(T);uint64_t E=0,S=0;for(int b=0;b<35;b++)if((T>>b)&1ULL){if(empty3(d[b],m.p))E|=1ULL<<b;if(single3(d[b],m.p))S|=1ULL<<b;}if(popcount(S)<3)return false;vector<int>sv;for(int b=0;b<35;b++)if((S>>b)&1ULL)sv.push_back(b);for(int i=0;i<(int)sv.size();i++)for(int j=i+1;j<(int)sv.size();j++)for(int k=j+1;k<(int)sv.size();k++){int n2=(d[sv[i]].inc==2)+(d[sv[j]].inc==2)+(d[sv[k]].inc==2);if(n2>1)continue;placements++;uint64_t ss=(1ULL<<sv[i])|(1ULL<<sv[j])|(1ULL<<sv[k]);uint64_t C=T&~E&~ss;int rc=trank(C);if(rc!=popcount(C))continue;if(rt-rc<4)continue;passes++;return true;}return false;}
int main(){init3();if(!ll3())return 10;if((long long)MOD*MOD<=14348907LL)return 11;auto reps=build_reps3();auto ms3=build_matchings3();long long all=0,h20=0,tests=0,places=0,passes=0,surv=0;for(auto&ms:reps){all++;uint64_t T;auto d=bdata3(ms,T);if(popcount(T)>20)continue;h20++;for(auto&m:ms3){tests++;if(survivor3(d,T,m,places,passes)){surv++;cout<<"SURVIVOR found\n";goto done;}}}done:cout<<"orbits "<<all<<" h20 "<<h20<<" matchings "<<ms3.size()<<" tests "<<tests<<" placements "<<places<<" passes "<<passes<<" survivors "<<surv<<"\n";bool ok=all==27763&&h20==13574&&ms3.size()==420&&tests==5701080&&places==676371&&passes==0&&surv==0;return ok?0:20;}
